namespace TutorFlow.Infrastructure.Llm;

public enum ProveedorLlm
{
    Anthropic,
    OpenAi,
    Groq,
    OpenRouter,
    Gemini,
    Ollama,
    OpenAiCompatible,
    Desconocido
}

public enum AdaptadorLlm
{
    Anthropic,
    CompatibleOpenAi,
    NoConfigurado
}

public sealed class ModeloConfigurado
{
    public string Nombre { get; init; } = string.Empty;
    public decimal PrecioEntradaPorMillon { get; init; }
    public decimal PrecioSalidaPorMillon { get; init; }
}

public sealed class ConfiguracionProveedor
{
    public string UrlBase { get; init; } = string.Empty;
    public string ModeloPorDefecto { get; init; } = string.Empty;
    public IReadOnlyList<ModeloConfigurado> Modelos { get; init; } = [];
}

public sealed class OpcionesLlm
{
    public const string Seccion = "Llm";

    public IReadOnlyDictionary<string, ConfiguracionProveedor> Proveedores { get; init; } = new Dictionary<string, ConfiguracionProveedor>();
}

public sealed record EntornoLlm(
    string? Llave,
    string? Proveedor,
    string? UrlBase,
    string? Modelo,
    decimal? PrecioEntrada,
    decimal? PrecioSalida);

public sealed record ProveedorResuelto(
    ProveedorLlm Proveedor,
    AdaptadorLlm Adaptador,
    string UrlBase,
    string Modelo,
    decimal PrecioEntradaPorMillon,
    decimal PrecioSalidaPorMillon,
    bool PrecioDesconocido,
    ConflictoDeProveedor? Conflicto = null);
namespace TutorFlow.Infrastructure.Llm;

public static class ResolutorProveedorLlm
{
    public static ProveedorResuelto Resolver(EntornoLlm entorno, OpcionesLlm opciones)
    {
        var urlExplicita = Limpiar(entorno.UrlBase);
        var determinacion = DeterminacionDelProveedor.Determinar(Limpiar(entorno.Proveedor), Limpiar(entorno.Llave), Limpiar(entorno.Modelo), urlExplicita);
        var proveedor = determinacion.Proveedor;
        var configuracion = ConfiguracionDe(proveedor, opciones);
        var modelo = ElegirModelo(entorno, configuracion);
        var precio = ResolverPrecio(entorno, configuracion, modelo);
        return new ProveedorResuelto(
            proveedor,
            AdaptadorDe(proveedor),
            ElegirUrl(proveedor, urlExplicita, configuracion),
            modelo,
            precio.Entrada,
            precio.Salida,
            precio.Desconocido,
            determinacion.Conflicto);
    }

    private static string ElegirModelo(EntornoLlm entorno, ConfiguracionProveedor? configuracion) =>
        Limpiar(entorno.Modelo) ?? configuracion?.ModeloPorDefecto ?? string.Empty;

    private static string ElegirUrl(ProveedorLlm proveedor, string? urlExplicita, ConfiguracionProveedor? configuracion) =>
        proveedor == ProveedorLlm.Desconocido ? string.Empty : urlExplicita ?? configuracion?.UrlBase ?? string.Empty;

    private static PrecioResuelto ResolverPrecio(EntornoLlm entorno, ConfiguracionProveedor? configuracion, string modelo)
    {
        var configurado = BuscarModelo(configuracion, modelo);
        return PrecioResuelto.De(
            entorno.PrecioEntrada ?? configurado?.PrecioEntradaPorMillon,
            entorno.PrecioSalida ?? configurado?.PrecioSalidaPorMillon);
    }

    private static ModeloConfigurado? BuscarModelo(ConfiguracionProveedor? configuracion, string modelo) =>
        configuracion?.Modelos.FirstOrDefault(m => m.Nombre == modelo);

    private sealed record PrecioResuelto(decimal Entrada, decimal Salida, bool Desconocido)
    {
        public static PrecioResuelto De(decimal? entrada, decimal? salida) =>
            new(entrada.GetValueOrDefault(), salida.GetValueOrDefault(), !entrada.HasValue || !salida.HasValue);
    }

    private static ConfiguracionProveedor? ConfiguracionDe(ProveedorLlm proveedor, OpcionesLlm opciones)
    {
        var clave = proveedor switch
        {
            ProveedorLlm.OpenAiCompatible or ProveedorLlm.Desconocido => nameof(ProveedorLlm.OpenAi),
            _ => proveedor.ToString()
        };
        return opciones.Proveedores.FirstOrDefault(par => string.Equals(par.Key, clave, StringComparison.OrdinalIgnoreCase)).Value;
    }

    private static AdaptadorLlm AdaptadorDe(ProveedorLlm proveedor) => proveedor switch
    {
        ProveedorLlm.Anthropic => AdaptadorLlm.Anthropic,
        ProveedorLlm.Desconocido => AdaptadorLlm.NoConfigurado,
        _ => AdaptadorLlm.CompatibleOpenAi
    };

    private static string? Limpiar(string? valor) =>
        string.IsNullOrWhiteSpace(valor) ? null : valor.Trim();
}
namespace TutorFlow.Api;

public static class ValidadorDeConfiguracion
{
    internal const string PrefijoInvalida = "Configuración inválida";
    internal const string PrefijoIgnorada = "Configuración ignorada";
    private const string SeccionModelos = "Llm:Proveedores";
    private const string PrecioDeEntrada = "PrecioEntradaPorMillon";
    private const string PrecioDeSalida = "PrecioSalidaPorMillon";

    public static IReadOnlyList<string> Validar(IConfiguration configuracion) =>
        [.. ReglasDeError(configuracion)
            .Where(regla => EsInvalido(configuracion, regla))
            .Select(regla => LineaInvalida(regla.Clave, configuracion[regla.Clave], regla.Texto))
            .Concat(ValidadorDeCatalogo.Validar(configuracion))];

    internal static string LineaInvalida(string clave, string? valor, string regla) =>
        Linea(PrefijoInvalida, clave, valor, regla);

    private static string Linea(string prefijo, string clave, string? valor, string regla) =>
        $"{prefijo}: {clave} = \"{ValorDeMensaje.De(valor)}\" ({regla})";

    internal static IReadOnlyList<string> Advertencias(IConfiguration configuracion) =>
        [.. ReglaDeConfiguracion.ConAdvertencia
            .Where(regla => EsInvalido(configuracion, regla))
            .Select(regla => $"{Linea(PrefijoIgnorada, regla.Clave, configuracion[regla.Clave], regla.Texto)}; se usa {regla.Defecto}")];

    internal static decimal? Efectivo(IConfiguration configuracion, string clave) =>
        ReglaDeConfiguracion.Buscar(clave).LeerValido(configuracion[clave]);

    private static IEnumerable<ReglaDeConfiguracion> ReglasDeError(IConfiguration configuracion) =>
        ReglaDeConfiguracion.Todas.Concat(ClavesDePrecioPorModelo(configuracion).Select(ReglaDeConfiguracion.Precio));

    private static IEnumerable<string> ClavesDePrecioPorModelo(IConfiguration configuracion) =>
        configuracion.GetSection(SeccionModelos).GetChildren()
            .SelectMany(proveedor => proveedor.GetSection("Modelos").GetChildren())
            .SelectMany(modelo => new[] { $"{modelo.Path}:{PrecioDeEntrada}", $"{modelo.Path}:{PrecioDeSalida}" });

    private static bool EsInvalido(IConfiguration configuracion, ReglaDeConfiguracion regla)
    {
        var valor = configuracion[regla.Clave];
        return !string.IsNullOrWhiteSpace(valor) && !regla.Cumple(valor);
    }
}
